contract InvMutTest {
    C c;

    constructor() { c = new C(address(this), address(this), address(this)); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(
        address baseTokenArg,
        address nftArg,
        uint128 virtualBaseTokenReservesArg,
        uint128 virtualNftReservesArg,
        uint56 changeFeeArg,
        uint16 feeRateArg,
        bytes32 merkleRootArg,
        bool useStolenNftOracleArg,
        bool payRoyaltiesArg
    ) public payable {
        require(feeRateArg <= 5000, "precondition: feeRate must be within allowed range");

        c.initialize(
            baseTokenArg,
            nftArg,
            virtualBaseTokenReservesArg,
            virtualNftReservesArg,
            changeFeeArg,
            feeRateArg,
            merkleRootArg,
            useStolenNftOracleArg,
            payRoyaltiesArg
        ); if (__ESBMC_reverted()) return;

        assert(c.baseToken() == baseTokenArg);
    }

    receive() external payable {}
}

