        feeRateArg = uint16(bound(uint256(feeRateArg), 0, 5000));
        try c.initialize(
            baseTokenArg,
            nftArg,
            virtualBaseTokenReservesArg,
            virtualNftReservesArg,
            changeFeeArg,
            feeRateArg,
            merkleRootArg,
            useStolenNftOracleArg,
            payRoyaltiesArg
        ) {} catch { return; }
        assertTrue(c.baseToken() == baseTokenArg);
    }

